type checkpointArchiveSizes struct {
	checkpoint     int64
	rootFsDiffTar  int64
}

// getCheckpointArchiveSizes retrieves the size of checkpoint archive components
// without unpacking the archive.
func getCheckpointArchiveSizes(input string) (checkpointArchiveSizes, error) {
	var sizes checkpointArchiveSizes

	archiveFile, err := os.Open(input)
	if err != nil {
		return sizes, err
	}
	defer archiveFile.Close()

	// Decompress the archive
	decompressedStream, err := archive.DecompressStream(archiveFile)
	if err != nil {
		return sizes, err
	}
	defer decompressedStream.Close()

	// Create a tar reader to read the files from the decompressed archive
	tarReader := tar.NewReader(decompressedStream)

	// Iterate through each file in the archive
	for {
		hdr, err := tarReader.Next()
		if err == io.EOF {
			// End of archive
			break
		}
		if err != nil {
			return sizes, err
		}

		// Check if it's a regular file
		if !hdr.FileInfo().IsDir() && strings.HasPrefix(hdr.Name, metadata.CheckpointDirectory) {
			// Add the file size to the total checkpoint size
			sizes.checkpoint += hdr.Size
		}

		if hdr.Name == metadata.RootFsDiffTar {
			sizes.rootFsDiffTar = hdr.Size
		}
	}

	return sizes, nil
}

